<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import ConfirmationCard from '@/components/ConfirmationCard.vue'
import type { ContractExperimentCreateBody, ContractSplitRandom } from '@/core/contract-types'
import type { ResourceRef } from '@/core/types'
import { useConfirmationStore } from '@/stores/confirmations'
import { useTrainingStore } from './store'

const store = useTrainingStore(); const confirmations = useConfirmationStore()
const projectId = ref(''); const name = ref(''); const dataVersionId = ref(''); const featureVersionId = ref(''); const targetField = ref(''); const taskType = ref(''); const selectedId = ref<string | null>(null); const templateId = ref(''); const protocolId = ref(''); const splitTrain = ref(0.8); const splitValidation = ref(0.1); const splitTest = ref(0.1); const randomSeed = ref(42); const parametersJson = ref('{}'); const error = ref<string | null>(null); const busy = ref(false)
const selected = computed(() => selectedId.value ? store.experiments.find((item) => item.id === selectedId.value) ?? store.selected : store.selected)
const resourceRef = computed<ResourceRef | null>(() => selected.value ? { id: selected.value.id, type: 'experiment' } : null)
const canSubmit = computed(() => Boolean(selected.value && resourceRef.value && confirmations.isFor(resourceRef.value, 'training.submit') && selected.value.status === 'READY'))
async function create() { const template = store.templates.find((item) => item.id === templateId.value); const protocol = store.protocols.find((item) => item.id === protocolId.value); const total = splitTrain.value + splitValidation.value + splitTest.value; const validFractions = [splitTrain.value, splitValidation.value, splitTest.value].every((value) => value > 0 && value < 1); if (!template || template.health !== 'READY' || !protocol || protocol.status !== 'APPROVED' || !template.evaluation_protocols.some((item) => item.id === protocol.id) || !template.allowed_targets.includes(targetField.value) || !template.feature_versions.includes(featureVersionId.value) || taskType.value !== template.task_type || !validFractions || Math.abs(total - 1) > 0.000001 || !Number.isInteger(randomSeed.value) || randomSeed.value < 0 || randomSeed.value > 2147483647) { error.value = '模板必须 READY；协议、特征、目标、任务类型、split 和随机种子必须符合服务端约束。'; return }; let parsed: unknown; try { parsed = JSON.parse(parametersJson.value) } catch { error.value = 'parameters 必须是 JSON 对象'; return }; if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') { error.value = 'parameters 必须是 JSON 对象'; return }; const parameters = parsed as Record<string, unknown>; const split: ContractSplitRandom = { strategy: 'random', random_seed: randomSeed.value, train_fraction: splitTrain.value, validation_fraction: splitValidation.value, test_fraction: splitTest.value }; const body: ContractExperimentCreateBody = { project_id: projectId.value, name: name.value, data_version_id: dataVersionId.value, feature_version_id: featureVersionId.value, target_field: targetField.value, task_type: taskType.value, evaluation_protocol: { id: protocol.id, version: protocol.version, status: 'APPROVED' }, execution: { kind: 'template', template_id: template.id, template_version: template.version }, parameters, resource_budget: template.resource_limits, split }; error.value = null; busy.value = true; try { const result = await store.createExperiment(body); selectedId.value = result.data.id } catch (reason) { error.value = reason instanceof Error ? reason.message : '训练草稿创建失败' } finally { busy.value = false } }
async function validate() { if (!selected.value) return; error.value = null; busy.value = true; try { await store.validateExperiment(selected.value.id, selected.value.spec.project_id, selected.value.etag); await store.getExperiment(selected.value.id, selected.value.spec.project_id) } catch (reason) { error.value = reason instanceof Error ? reason.message : '服务端校验不可用' } finally { busy.value = false } }
async function submit() { if (!selected.value || !canSubmit.value) return; error.value = null; busy.value = true; try { await store.submitExperiment(selected.value.id, selected.value.spec.project_id, confirmations.confirmation!.id) } catch (reason) { error.value = reason instanceof Error ? reason.message : '训练提交不可用' } finally { busy.value = false } }
onMounted(() => { void store.listTemplates().catch(() => undefined); void store.listProtocols(taskType.value).catch(() => undefined) })
</script>
<template>
  <div class="view"><header class="page-header"><span class="eyebrow">TRAINING · FROZEN M3/M4 API</span><h1>模型训练</h1><p>固定模板实验必须经过服务端校验、确认和异步提交；不执行任意脚本。</p></header>
    <section class="panel"><h2>训练草稿</h2><div class="grid two-column"><label>项目 ID<input v-model="projectId" /></label><label>名称<input v-model="name" /></label><label>数据版本 ID<input v-model="dataVersionId" /></label><label>特征版本 ID<input v-model="featureVersionId" /></label><label>目标字段<input v-model="targetField" /></label><label>任务类型<input v-model="taskType" /></label><label>服务端模板<select v-model="templateId"><option value="">请选择</option><option v-for="item in store.templates" :key="item.id" :value="item.id">{{ item.id }} · {{ item.version }} · {{ item.health }}</option></select></label><label>已批准评测协议<select v-model="protocolId"><option value="">请选择</option><option v-for="item in store.protocols.filter((candidate) => candidate.status === 'APPROVED')" :key="item.id" :value="item.id">{{ item.id }} · {{ item.version }}</option></select></label><label>随机种子<input v-model.number="randomSeed" type="number" /></label><label>训练比例<input v-model.number="splitTrain" type="number" min="0" max="1" step="0.05" /></label><label>验证比例<input v-model.number="splitValidation" type="number" min="0" max="1" step="0.05" /></label><label>测试比例<input v-model.number="splitTest" type="number" min="0" max="1" step="0.05" /></label></div><label class="wide-field">parameters JSON<textarea v-model="parametersJson" rows="3" /></label><button class="primary" :disabled="busy || !projectId || !name || !dataVersionId || !featureVersionId || !targetField || !taskType || !templateId || !protocolId" @click="create">{{ busy ? '处理中…' : '创建服务端草稿' }}</button><p v-if="error" class="error-text">{{ error }}</p></section>
    <section class="panel"><h2>实验列表</h2><button class="secondary" :disabled="!projectId || store.state === 'loading'" @click="store.listExperiments(projectId)">读取项目实验</button><div v-if="store.state === 'loading'" class="placeholder">正在读取…</div><div v-else-if="store.state === 'error'" class="error-text">{{ store.error }}</div><div v-else-if="!store.experiments.length" class="placeholder">服务端未返回实验。</div><div v-else class="event-list"><button v-for="item in store.experiments" :key="item.id" class="secondary" @click="selectedId = item.id; void store.getExperiment(item.id, projectId)">{{ item.id }} · {{ item.status }} · revision {{ item.revision }}</button></div></section>
    <section v-if="selected" class="panel"><h2>实验 {{ selected.id }}</h2><p class="muted">{{ selected.status }} · ETag {{ selected.etag }}</p><button class="secondary" :disabled="busy" @click="validate">执行服务端校验</button><p v-if="store.validation" class="muted">校验：{{ store.validation.valid ? '可提交' : '未通过' }}</p><ConfirmationCard v-if="resourceRef" :resource-ref="resourceRef" action="training.submit" /><button class="primary" :disabled="busy || !canSubmit" @click="submit">提交训练（需确认）</button></section>
  </div>
</template>
